package cl.bolsillo.app;
import android.content.*;import android.app.*;import org.json.*;
/** Isolated emulator checks; restores the original encrypted state and preferences afterwards. */
final class AlertChecks {
 interface Check {void yes(boolean value,String message)throws Exception;}
 static void run(Context c,Check check)throws Exception{
  JSONObject saved=NativeStore.state(c);boolean changes=NativeStore.settings(c).getBoolean("alertChanges",true),detections=NativeStore.settings(c).getBoolean("alertDetections",true),reviews=NativeStore.settings(c).getBoolean("alertVerifications",true),privacy=LocalAlerts.hidden(c);
  try{
   JSONObject state=new JSONObject(saved.toString()).put("cache",new JSONObject().put("ownerId","alert-test-owner").put("version",1).put("data",Ledger.initial())).put("queue",new JSONArray()).put("localAlertHistory",new JSONArray()).put("localAlertSignatures",new JSONObject());NativeStore.write(c,state);
   NativeStore.settings(c).edit().putBoolean("alertChanges",false).putBoolean("alertDetections",false).putBoolean("alertVerifications",false).putBoolean("alertHideAmounts",false).commit();
   JSONObject tx=NativeSync.transaction("expense",4000,"bank-mach","","expense-0","Privado para cifrar","manual","").put("id","alert-test-tx");LocalData.upsert(c,"transactions",tx);check.yes(LocalAlerts.history(c).length()==1,"disabled Android notices still keep encrypted local history");
   String ledger=LocalData.read(c).toString();LocalData.upsert(c,"transactions",tx);check.yes(LocalAlerts.history(c).length()==1,"same commit and sync echo are quiet");check.yes(LocalData.read(c).toString().equals(ledger),"notices do not change financial records");
   JSONObject before=LocalData.read(c);tx.put("amount",5500);LocalData.upsert(c,"transactions",tx);check.yes(LocalAlerts.history(c).length()==2,"committed amount edit creates one notice");
   LocalAlerts.changed(c,before,LocalData.read(c));check.yes(LocalAlerts.history(c).length()==2,"same state echo does not notify twice");
   tx.put("amount",4000);LocalData.upsert(c,"transactions",tx);tx.put("amount",5500);LocalData.upsert(c,"transactions",tx);check.yes(LocalAlerts.history(c).length()==4,"changing back and then forward are real new edits");
   String encrypted=c.getSharedPreferences("secure",0).getString("state","");check.yes(!encrypted.contains("Privado para cifrar")&&!encrypted.contains("localAlertHistory"),"alert titles amounts and history encrypted at rest");
   JSONObject evidence=new JSONObject().put("id","alert-review").put("merchant","Comercio ambiguo").put("amount",7777).put("reason","Elige la cuenta").put("label","Banco sintético");LocalAlerts.detected(c,evidence,null);LocalAlerts.detected(c,evidence,null);JSONArray history=LocalAlerts.history(c);check.yes(history.length()==5&&history.getJSONObject(4).optString("channel").equals(LocalAlerts.VERIFICATIONS),"review deduplicated in verification channel");
   JSONObject suppressed=new JSONObject(evidence.toString()).put("id","alert-suppressed").put("suppressed",true);LocalAlerts.detected(c,suppressed,null);check.yes(LocalAlerts.history(c).length()==5,"safe bank wallet duplicate emits no alert");
   JSONObject posted=NativeSync.transaction("expense",7777,"bank-mach","","expense-0","Comercio ambiguo","notification","alert-review").put("status","posted");LocalAlerts.detected(c,evidence,posted);check.yes(LocalAlerts.history(c).length()==6&&LocalAlerts.history(c).getJSONObject(4).optBoolean("resolved"),"confirmation creates one notice and resolves previous review");LocalAlerts.detected(c,evidence,posted);check.yes(LocalAlerts.history(c).length()==6,"confirmation echo is quiet");
   JSONObject after=new JSONObject(before.toString());after.getJSONArray("transactions").put(posted);LocalAlerts.changed(c,before,after);check.yes(LocalAlerts.history(c).length()==6,"detection is not announced again as manual change");
   NativeStore.settings(c).edit().putBoolean("alertHideAmounts",true).commit();check.yes(LocalAlerts.hidden(c),"privacy choice saved");JSONObject backup=LocalData.backup(c);check.yes(backup.getJSONArray("localAlertHistory").length()==6&&backup.getJSONObject("settings").optBoolean("alertHideAmounts"),"backup includes encrypted store history and channel preferences on explicit export");
   LocalAlerts.channels(c);NotificationManager manager=c.getSystemService(NotificationManager.class);check.yes(manager.getNotificationChannel(LocalAlerts.CHANGES)!=null&&manager.getNotificationChannel(LocalAlerts.DETECTIONS)!=null&&manager.getNotificationChannel(LocalAlerts.VERIFICATIONS)!=null,"three native Android channels available");
   if(LocalAlerts.available(c)){
    manager.cancelAll();NativeStore.settings(c).edit().putBoolean("alertChanges",true).putBoolean("alertHideAmounts",false).commit();tx.put("amount",6500);LocalData.upsert(c,"transactions",tx);Thread.sleep(150);android.service.notification.StatusBarNotification[] active=manager.getActiveNotifications();check.yes(active.length==1&&active[0].getNotification().getChannelId().equals(LocalAlerts.CHANGES),"real Android notice posted on changes channel");check.yes(active[0].getNotification().contentIntent!=null&&active[0].getNotification().contentIntent.getCreatorPackage().equals(c.getPackageName()),"tap intent belongs to Bolsillo");
    manager.cancelAll();NativeStore.settings(c).edit().putBoolean("alertHideAmounts",true).commit();tx.put("amount",7500);LocalData.upsert(c,"transactions",tx);Thread.sleep(150);active=manager.getActiveNotifications();String body=active[0].getNotification().extras.getString(Notification.EXTRA_TEXT,"");check.yes(active.length==1&&!body.contains("$")&&!body.matches(".*[0-9].*"),"hidden amount also removed from real system notification");
   }
   LocalAlerts.clearHistory(c);check.yes(LocalAlerts.history(c).length()==0,"clear affects only notice history");LocalAlerts.detected(c,evidence,posted);check.yes(LocalAlerts.history(c).length()==0,"clearing history does not replay old detection");
  }finally{NativeStore.write(c,saved);NativeStore.settings(c).edit().putBoolean("alertChanges",changes).putBoolean("alertDetections",detections).putBoolean("alertVerifications",reviews).putBoolean("alertHideAmounts",privacy).commit();}
 }
}
